-- Hyprland entry point. Each file under hyprland/ covers one area; order matters.
--
-- Files that stay local to this machine (not in the dotfiles repo):
--   hyprland/colors.lua       generated by matugen from the wallpaper
--   hyprmoncfg-monitors.lua   monitors + workspace placement, generated by hyprmoncfg

require("hyprland.lib")
require("hyprland.variables")
require("hyprland.env")
require("hyprland.execs")
require("hyprland.general")
require("hyprland.animations")
require("hyprland.rules")
require("hyprland.colors")
require("hyprland.keybinds")

-- Loaded last so the monitor layout applied by hyprmoncfg always wins
dofile_if_exists(HOME .. "/.config/hypr/hyprmoncfg-monitors.lua")

-- Added by hyprmoncfg: its generated monitor rules load last, so nothing before this can override the applied layout.
do local path = os.getenv("HOME") .. "/.config/hypr/hyprmoncfg-monitors.lua"; local file = io.open(path, "r"); if file then file:close(); dofile(path) end end
